#include "polyphase_float_mpfr.h"
#include <stdio.h>
#include <stdlib.h>
#define CHECK(c)do{if(!(c)){fprintf(stderr,"FAIL %s:%d %s\n",__FILE__,__LINE__,#c);exit(1);}}while(0)
static const ppf_rnd_t pr[5]={PPF_RNDN,PPF_RNDZ,PPF_RNDU,PPF_RNDD,PPF_RNDA};static const mpfr_rnd_t mr[5]={MPFR_RNDN,MPFR_RNDZ,MPFR_RNDU,MPFR_RNDD,MPFR_RNDA};static int sg(int x){return(x>0)-(x<0);}static int same(const ppf_t*p,mpfr_srcptr m){mpfr_t g;mpfr_init2(g,mpfr_get_prec(m));ppf_get_mpfr(g,p,MPFR_RNDN);int o=mpfr_equal_p(g,m)||(mpfr_nan_p(g)&&mpfr_nan_p(m))||(mpfr_inf_p(g)&&mpfr_inf_p(m)&&mpfr_signbit(g)==mpfr_signbit(m))||(mpfr_zero_p(g)&&mpfr_zero_p(m)&&mpfr_signbit(g)==mpfr_signbit(m));if(!o)mpfr_printf("got %.30Rg ref %.30Rg\n",g,m);mpfr_clear(g);return o;}static int fl(ppf_context_t*c){unsigned p=c->flags;return!!(p&1)==!!mpfr_underflow_p()&&!!(p&2)==!!mpfr_overflow_p()&&!!(p&4)==!!mpfr_divby0_p()&&!!(p&8)==!!mpfr_nanflag_p()&&!!(p&16)==!!mpfr_inexflag_p()&&!!(p&32)==!!mpfr_erangeflag_p();}
typedef int(*pu)(ppf_t*,const ppf_t*,ppf_rnd_t,ppf_context_t*);typedef int(*mu)(mpfr_ptr,mpfr_srcptr,mpfr_rnd_t);static void one(const char*n,pu f,mu g,const char*s){ppf_context_t c;ppf_t x,y;mpfr_t mx,my;ppf_context_init(&c);ppf_context_set_range(&c,-20,20);ppf_init2_ctx(&x,80,&c);ppf_init2_ctx(&y,24,&c);mpfr_init2(mx,80);mpfr_init2(my,24);mpfr_set_str(mx,s,10,MPFR_RNDN);ppf_set_mpfr(&x,mx,PPF_RNDN,&c);for(int i=0;i<5;i++){c.flags=0;mpfr_clear_flags();int a=f(&y,&x,pr[i],&c),b=g(my,mx,mr[i]);if(a==PPF_TERNARY_ERROR||!same(&y,my)||sg(a)!=sg(b)||!fl(&c)){fprintf(stderr,"%s(%s) rnd%d rc%d/%d pf%x mf%d%d%d%d%d%d\n",n,s,i,a,b,c.flags,mpfr_underflow_p()!=0,mpfr_overflow_p()!=0,mpfr_divby0_p()!=0,mpfr_nanflag_p()!=0,mpfr_inexflag_p()!=0,mpfr_erangeflag_p()!=0);exit(1);}}ppf_clear(&x);ppf_clear(&y);ppf_context_clear(&c);mpfr_clear(mx);mpfr_clear(my);}int main(void){mpfr_exp_t oe=mpfr_get_emin(),ox=mpfr_get_emax();mpfr_set_emin(-20);mpfr_set_emax(20);const char*v[]={"-100","-30","-20","20","30","100"};for(int i=0;i<6;i++){one("exp",ppf_exp,mpfr_exp,v[i]);one("exp2",ppf_exp2,mpfr_exp2,v[i]);one("exp10",ppf_exp10,mpfr_exp10,v[i]);one("expm1",ppf_expm1,mpfr_expm1,v[i]);}mpfr_set_emin(oe);mpfr_set_emax(ox);puts("range transcendental differential passed");return 0;}
